/// The key event, as the keyboard reported it.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub struct KeyInput {
    /// The physical key, named after its W3C KeyboardEvent code in snake_case, such as key_a for
    /// KeyA, the A key on a US keyboard. It doesn't change with the keyboard layout. Any other key
    /// is unidentified.
    pub key: KeyCode,
    /// The modifier keys held down, joined with + in this order: shift, ctrl, alt, super,
    /// caps_lock, num_lock, shift_side, ctrl_side, alt_side, super_side. On a Mac, super is the
    /// Command key. The lock names mean the lock is on, and a name ending in _side means the
    /// right-hand key of that pair is held. An empty string means none.
    pub mods: String,
    /// The modifiers the keyboard layout used to produce text, such as shift for a capital letter.
    /// Written like mods, which also includes them.
    pub consumed_mods: String,
    /// The text the key typed. Empty for keys that type nothing, such as arrows and modifiers.
    pub text: String,
    /// The Unicode code point the key types without shift, such as 110 for n. Bindings such as
    /// ctrl+n match on it, so they follow the keyboard layout. 0 if none.
    pub unshifted_codepoint: i64,
    /// True while the key is part of an unfinished composition, such as a dead key or an input
    /// method.
    pub composing: bool,
    /// What happened to the key: press, release, or repeat while it's held down.
    pub action: KeyAction,
}

impl KeyInput {
    /// Creates a `KeyInput` with its required fields.
    pub fn new(
        key: KeyCode,
        mods: impl Into<String>,
        consumed_mods: impl Into<String>,
        text: impl Into<String>,
        unshifted_codepoint: i64,
        composing: bool,
        action: KeyAction,
    ) -> Self {
        Self {
            key,
            mods: mods.into(),
            consumed_mods: consumed_mods.into(),
            text: text.into(),
            unshifted_codepoint,
            composing,
            action,
        }
    }
}

/// Send a key to a block, giving Lua key bindings the first chance at it.
///
/// - The connection must be attached to `session_id`, with `session.attach`, `session.bootstrap`,
///   or `session.attach_all`, or the call fails with `conflict`. If `session_id` names no
///   session, the call fails with `session_not_found`.
/// - Without `block_id`, the key goes to the session's focused block. The server reads it once,
///   before any Lua function runs, so a function that moves focus doesn't change where the key
///   goes. Either way, Lua functions see the block the key goes to as `ctx.block_id`.
/// - On each connection, `client.key`, `client.action`, `block.event`, and the methods that
///   change focus or the layout run one at a time, in the order they arrive. That keeps keys in
///   the order you send them.
/// - The key goes first to the Lua functions bound to it in this client's scripts, then to those
///   in the configuration file. If none of them takes the key, it goes to the block.
/// - Only a key bound to a Lua function reaches Lua, and only when it's pressed or repeating.
///   Every other key goes straight to the block. `client.keymap` reports the bound keys as
///   bindings for `client.key.forward`.
/// - If no Lua function takes the key and the session has no focused block, the key goes nowhere.
///   The call still succeeds, with `handled` set to false.
/// - To send a key sequence, wait until it's complete. Then send its last key as `key` and the
///   keys before it in `prefix`, such as `["ctrl+b"]`. The server doesn't remember keys between
///   requests.
/// - A key with a `prefix` reaches only the functions bound to that exact sequence. A key without
///   one reaches only the functions bound to that key alone.
/// - If no function takes a key sequence, only `key` goes on to the block. The keys in `prefix`
///   never do.
/// - A Lua function bound to a key may run for 5 seconds. If it raises an error or runs longer,
///   the call fails and the key doesn't reach the block.
/// - If an element of `prefix` isn't a key the server can read, the call fails with
///   `bad_request`, and the message names the element.
/// - If no Lua function takes the key and `block_id` names a block that isn't in the session, the
///   call fails with `not_found`.
///
/// Wire method: `client.key`.
///
/// # Example
///
/// ```json
/// {
///   "session_id": "session:<uuid>",
///   "key": {
///     "key": "key_g",
///     "mods": "ctrl",
///     "consumed_mods": "",
///     "text": "",
///     "unshifted_codepoint": 103,
///     "composing": false,
///     "action": "press"
///   }
/// }
/// ```
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub struct Key {
    /// The session the key is typed in.
    pub session_id: String,
    /// The key event, as the keyboard reported it.
    pub key: KeyInput,
    /// The block to send the key to. Defaults to the session's focused block.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub block_id: Option<String>,
    /// The keys pressed before key when key ends a key sequence, in order. For ctrl+b then x, send
    /// x as key and ctrl+b here.
    #[serde(
        default,
        deserialize_with = "crate::api::nullable",
        skip_serializing_if = "Vec::is_empty"
    )]
    pub prefix: Vec<String>,
}

impl Key {
    /// Creates a `Key` with its required fields.
    pub fn new(session_id: impl Into<String>, key: KeyInput) -> Self {
        Self {
            session_id: session_id.into(),
            key,
            block_id: Default::default(),
            prefix: Default::default(),
        }
    }

    /// The block to send the key to. Defaults to the session's focused block.
    pub fn block_id(mut self, value: impl Into<String>) -> Self {
        self.block_id = Some(value.into());
        self
    }

    /// The keys pressed before key when key ends a key sequence, in order. For ctrl+b then x, send
    /// x as key and ctrl+b here.
    pub fn prefix(mut self, value: impl IntoIterator<Item = impl Into<String>>) -> Self {
        self.prefix = value.into_iter().map(Into::into).collect();
        self
    }
}

impl crate::api::Method for Key {
    const NAME: &'static str = "client.key";
    type Response = KeyResponse;
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
#[non_exhaustive]
pub struct Binding {
    /// The keys that trigger the binding, such as cmd+k, or cmd+\[KeyK\] for a key by its position.
    /// A key sequence has one element per key, in the order pressed.
    #[serde(default, deserialize_with = "crate::api::nullable")]
    pub keys: Vec<String>,
    /// The name of the action to run.
    pub action: String,
    /// The arguments to run the action with, as a JSON object, exactly as the user wrote them. Left
    /// out if there are none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub args: Option<serde_json::Value>,
    /// Where the binding came from: a layer name, such as default, or a file:line, such as
    /// init.lua:12. Ignored in a request.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
    /// The mode the binding belongs to, such as resize. The binding applies only while that mode is
    /// active. Left out for a binding outside every mode.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<String>,
}

impl Binding {
    /// Creates a `Binding` with its required fields.
    pub fn new(
        keys: impl IntoIterator<Item = impl Into<String>>,
        action: impl Into<String>,
    ) -> Self {
        Self {
            keys: keys.into_iter().map(Into::into).collect(),
            action: action.into(),
            args: Default::default(),
            source: Default::default(),
            mode: Default::default(),
        }
    }

    /// The arguments to run the action with, as a JSON object, exactly as the user wrote them. Left
    /// out if there are none.
    pub fn args(mut self, value: serde_json::Value) -> Self {
        self.args = Some(value);
        self
    }

    /// Where the binding came from: a layer name, such as default, or a file:line, such as
    /// init.lua:12. Ignored in a request.
    pub fn source(mut self, value: impl Into<String>) -> Self {
        self.source = Some(value.into());
        self
    }

    /// The mode the binding belongs to, such as resize. The binding applies only while that mode is
    /// active. Left out for a binding outside every mode.
    pub fn mode(mut self, value: impl Into<String>) -> Self {
        self.mode = Some(value.into());
        self
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
pub struct Diagnostic {
    /// How serious the problem is: warning, for something the user probably didn't mean, or error,
    /// for a part that was skipped. Show a value you don't know as a warning.
    pub severity: String,
    /// Where the problem is, as file:line, such as init.lua:22. Left out when it isn't known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
    /// The problem in one sentence, ready to show. Its wording may change, so don't parse it.
    pub message: String,
    /// The full name of the action the problem is about, as written, even if misspelled. Left out
    /// if it isn't about one action.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action: Option<String>,
    /// The key the problem is about, spelled like a binding's keys, with a sequence joined by
    /// spaces, such as ctrl+a b. Left out if it isn't about one key.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub key: Option<String>,
    /// The mode the problem is about. Left out if it isn't about a mode.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<String>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
pub struct Mode {
    /// The mode's name, such as resize. Its bindings have it as their mode, and client.mode.enter
    /// takes it as its name argument.
    pub name: String,
    /// True if keys the mode doesn't bind are ignored while it's active. If false, they do what
    /// they do outside the mode.
    pub exclusive: bool,
    /// Keys that must not reach the bindings outside the mode while it's active. If the mode also
    /// binds one, that binding still runs. Each is spelled like a binding's keys.
    #[serde(
        default,
        deserialize_with = "crate::api::nullable",
        skip_serializing_if = "Vec::is_empty"
    )]
    pub blocked: Vec<Option<Vec<String>>>,
}

/// The configuration file the keymap came from. Present even when the file doesn't exist, so you
/// can tell the user where to create it.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
pub struct Config {
    /// The absolute path of the configuration file, whether or not it exists.
    pub path: String,
    /// True if the file existed when the server last read it.
    pub exists: bool,
    /// How many times the server has loaded its configuration file since it started, counting from
    /// 1. It goes up even when the file didn't change, so compare hash and instance_id, not this,
    /// to tell whether a keymap you kept is current.
    pub generation: u64,
    /// The ID of the server process, as server.status reports it. A new value means the server
    /// restarted, so send your client.set_script scripts again.
    pub instance_id: String,
    /// The SHA-256 of the configuration file and the modules it requires while it loads, in
    /// lowercase hexadecimal. Empty if there's no file or it couldn't be read.
    pub hash: String,
}

/// The result of [`Keymap`].
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
