///       "name": "init.lua",
///       "source": "rex.bind(\"ctrl+g\", function(ctx, ev)\n  rex.session.set_label{ label = \"work\" }\n  return true\nend)\nrex.bind(\"ctrl+hoem\", \"pane.zoom\")"
///     }
